(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  // Escape first; support only a small, safe formatting subset (never raw HTML).
  const rich = s => esc(s).replace(/^#{1,3} (.+)$/gm,'<strong>$1</strong>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
  const paths = {grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',office:'M3 21V7l9-4 9 4v14 M3 21h18 M9 21v-6h6v6 M7 9h2 M15 9h2 M7 12h2 M15 12h2',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5z M8 10h8 M8 14h5',tasks:'M9 5h11 M9 12h11 M9 19h11 M3 5l1 1 2-3 M3 12l1 1 2-3 M3 19l1 1 2-3',database:'M3 6c0-5 18-5 18 0s-18 5-18 0v12c0 5 18 5 18 0V6 M3 12c0 5 18 5 18 0',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 5v14 M5 12h14',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 3 M18 18A8 8 0 0 1 5 15',close:'m6 6 12 12 M6 18 18 6',menu:'M4 6h16 M4 12h16 M4 18h16',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a7 7 0 0 1 14 0v2 M17 5a4 4 0 0 1 0 7 M19 16a5 5 0 0 1 3 5',chart:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17V3',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',send:'m3 3 19 9-19 9 4-9-4-9 M7 12h15',link:'m9 15 6-6 M9 7l2-2a5 5 0 0 1 7 7l-2 2 M15 17l-2 2a5 5 0 0 1-7-7l2-2',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
  document.querySelectorAll('[data-icon]').forEach(el => el.innerHTML = icon(el.dataset.icon));
  const departments = {ops:'Operations',marketing:'Marketing',fin:'Finance',sales:'Sales',delivery:'Delivery',emails:'Communication'};
  const profiles = {olead:['Aria','Briefing lead','AR'],scout:['Nara','Data analyst','NA'],legal:['Sora','Fact checker','SO'],report:['Raya','Brief writer','RA'],dash:['Kira','Dashboard planner','KI']};
  const colors = ['#e5f3f6','#eeeafa','#f7efe4','#eaf2e9','#e9effa'];
  const profile = id => { const a = state.agents.find(x => x.id === id); return a?.displayName?[a.displayName,a.displayRole,a.displayName.slice(0,2).toUpperCase()]:profiles[id] || [a?.name?.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()) || id,a?.role || 'AI agent',(a?.name || id).slice(0,2)]; };
  const avatar = id => `<span class="avatar" style="background:${colors[Math.max(0,state.agents.findIndex(a=>a.id===id))%colors.length]}">${esc(profile(id)[2])}</span>`;
  const state = { health:null, agents:[], tasks:[], documents:[], telegram:null, page:'overview', target:'olead', conversation:null, filter:'all', query:'', busy:false, taskDialog:null, refreshing:false, online:false, officeDept:null, chatting:[], zoom:1, motion:!matchMedia('(prefers-reduced-motion: reduce)').matches };
  let lastConversation = '', lastTasks = '', toastTimer;
  const drafts = new Map();
  let scene3d = null;
  let sceneScript = null;
  async function mountOfficeScene(host){
    try{if(!window.Office3D){sceneScript||=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URLSearchParams(location.search).get('characters')==='classic'?'./studio3d.js':'./studio3d-human.js?v=6';script.onload=resolve;script.onerror=()=>{sceneScript=null;script.remove();reject(Error('Kantor gagal dimuat. Segarkan untuk mencoba lagi.'));};document.head.append(script);});await sceneScript;}
      if(!host.isConnected||host!==$('#office-3d'))return;
      scene3d=window.Office3D.mount(host,{agents:state.agents,profile,onAgent:openOfficeBubble,onDepartment:selectOfficeDepartment,motion:state.motion,full:true});window.officeScene=scene3d;scene3d.update(state.chatting,state.tasks);scene3d.focus(state.officeDept);host.querySelector('.scene-loading')?.remove();syncSceneNavigation();
    }catch(err){if(host.isConnected)host.querySelector('.scene-loading').textContent=err.message;}
  }
  function syncSceneNavigation(){const host=$('#office-3d');if(!host)return;$('#scene-department').value=state.officeDept||'';$('#scene-back').hidden=!state.officeDept;host.querySelector('.scene-guide').textContent=state.officeDept?'02 · '+departments[state.officeDept]+' · klik agent untuk chat':'01 · Pilih blok divisi, lalu klik agent untuk chat';}
  function selectOfficeDepartment(dept){closeOfficeBubble();state.officeDept=departments[dept]?dept:null;const hash='#office'+(state.officeDept?'/'+state.officeDept:'');if(location.hash!==hash)location.hash=hash;else{scene3d?.focus(state.officeDept);syncSceneNavigation();}}
  async function toggleOfficeFullscreen(){const host=$('#office-3d');if(!host)return;try{if(document.fullscreenElement===host)await document.exitFullscreen();else if(host.classList.contains('expanded-office')){host.classList.remove('expanded-office');document.body.classList.remove('office-expanded');}else if(host.requestFullscreen)await host.requestFullscreen();else{host.classList.add('expanded-office');document.body.classList.add('office-expanded');}}catch{host.classList.toggle('expanded-office');document.body.classList.toggle('office-expanded',host.classList.contains('expanded-office'));}syncFullscreen();}
  function syncFullscreen(){const host=$('#office-3d'),button=$('#scene-fullscreen');if(!button)return;const on=document.fullscreenElement===host||host.classList.contains('expanded-office');button.setAttribute('aria-pressed',String(on));button.setAttribute('aria-label',on?'Keluar fullscreen':'Buka fullscreen');button.querySelector('span').textContent=on?'Keluar':'Fullscreen';}
  document.addEventListener('fullscreenchange',syncFullscreen);
  document.addEventListener('change',e=>{if(e.target.id==='scene-department')selectOfficeDepartment(e.target.value);});
  document.addEventListener('click',e=>{if(e.target.closest('#scene-fullscreen'))toggleOfficeFullscreen();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!officeBubble&&$('#office-3d')?.classList.contains('expanded-office'))toggleOfficeFullscreen();});
  let officeBubble = null;
  const bubbleDrafts = new Map();
  const bubbleAttachments = new Map();
  const imageURL=id=>'./api/studio/documents/'+encodeURIComponent(id)+'/preview';
  const attachmentMarkup=m=>(m.attachments||[]).map(d=>d.type==='image'?`<a class="chat-attachment-image" href="${imageURL(d.id)}" target="_blank" rel="noopener"><img src="${imageURL(d.id)}" alt="${esc(d.name)}" loading="lazy"></a>`:`<small class="chat-file-name">${icon('file')} ${esc(d.name)}</small>`).join('');
  function paintBubbleAttachments(b){if(officeBubble!==b)return;const list=bubbleAttachments.get(b.id)||[];b.el.querySelector('.bubble-attachments').innerHTML=list.map(d=>`<span class="bubble-attachment">${d.type==='image'?`<img src="${imageURL(d.id)}" alt="">`:icon('file')}<span>${esc(d.name)}</span><button type="button" data-remove-attachment="${esc(d.id)}" aria-label="Lepas ${esc(d.name)}">×</button></span>`).join('');b.el.querySelectorAll('[data-remove-attachment]').forEach(btn=>btn.onclick=()=>{bubbleAttachments.set(b.id,(bubbleAttachments.get(b.id)||[]).filter(d=>d.id!==btn.dataset.removeAttachment));paintBubbleAttachments(b);});}
  async function addBubbleFiles(files,b){
    if(!files||!files.length||!b)return;
    const file=files[0];
    const reader=new FileReader();
    reader.onload=async()=>{
      try{
        const doc=await api('/api/studio/documents',{name:file.name,content:reader.result,bytes:file.size,type:file.type.startsWith('image/')?'image':'text'},'POST');
        const list=bubbleAttachments.get(b.id)||[];
        list.push(doc);
        bubbleAttachments.set(b.id,list);
        paintBubbleAttachments(b);
      }catch(err){toast('Gagal melampirkan file: '+err.message);}
    };
    if(file.type.startsWith('image/'))reader.readAsDataURL(file);
    else reader.readAsText(file);
  }
  function closeOfficeBubble(focus=false){
    if(!officeBubble)return;
    officeBubble.disposeVoice?.();
    bubbleDrafts.set(officeBubble.id,officeBubble.el.querySelector('textarea').value);
    officeBubble.observer.disconnect();cancelAnimationFrame(officeBubble.frame);
    officeBubble.el.remove();officeBubble=null;
    if(focus)$('#office-3d canvas')?.focus({preventScroll:true});
  }
  function openOfficeBubble(id){
    const host=$('#office-3d');if(!host)return;
    if(officeBubble?.id===id){officeBubble.el.querySelector('textarea').focus({preventScroll:true});return;}
    closeOfficeBubble();
    const el=document.createElement('section');el.className='office-chat-bubble';el.setAttribute('role','dialog');el.setAttribute('aria-label','Chat dengan '+profile(id)[0]);
    el.innerHTML=`<header>${avatar(id)}<div><strong>${esc(profile(id)[0])}</strong><small>${esc(profile(id)[1])}</small></div><button type="button" class="bubble-close" aria-label="Tutup chat">${icon('close')}</button></header><div class="bubble-messages" aria-live="polite" aria-relevant="additions text"><p class="bubble-empty">Memuat percakapan…</p></div><p class="bubble-error" role="alert" hidden></p><form><label class="sr-only" for="office-bubble-input">Pesan untuk ${esc(profile(id)[0])}</label><textarea id="office-bubble-input" rows="2" maxlength="6000" placeholder="Tanya ${esc(profile(id)[0])}…" required></textarea><div class="bubble-attachments"></div><div class="bubble-compose-footer"><button type="button" class="bubble-upload" aria-label="Upload file atau gambar">${icon('plus')}</button><input class="bubble-file-input" type="file" accept=".png,.jpg,.jpeg,.webp,.csv,.txt,.md,.json" multiple hidden><select aria-label="Lampirkan dokumen"><option value="">Tanpa lampiran</option>${state.documents.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select><button type="submit" aria-label="Kirim pesan" disabled>${icon('send')}</button></div><small class="bubble-upload-status">PNG/JPG/WebP ≤2 MB · teks/CSV ≤32 KB</small></form><footer>Chat aktif dengan ${esc(profile(id)[0])} · SondeR AI Office</footer>`;
    host.append(el);const bubble={id,el,key:'',revision:0,pending:false,sending:false,loading:false,ready:false,frame:0};officeBubble=bubble;
    bubble.disposeVoice=window.OfficeLive?.mount(el,id,profile(id)[0],()=>{if(officeBubble===bubble){bubble.key='';loadOfficeBubble();}});
    const position=()=>{if(officeBubble!==bubble)return;const target=scene3d?.inspect().targets.find(t=>t.id===id);const w=host.clientWidth,h=host.clientHeight;
      const humanPreview=Number(host.dataset.humanAvatars)>0;
      const x=w<650?(w-el.offsetWidth)/2:humanPreview?w-el.offsetWidth-16:Math.max(12,Math.min(w-el.offsetWidth-12,(target?.x||w/2)+30));
      const y=w<650?h-el.offsetHeight-12:Math.max(70,Math.min(h-el.offsetHeight-12,(target?.y||h/2)-el.offsetHeight*.5));
      const left=Math.round(x)+'px',top=Math.round(y)+'px',tail=Math.round(Math.max(28,Math.min(el.offsetHeight-28,(target?.y||h/2)-y)))+'px';if(el.style.left!==left)el.style.left=left;if(el.style.top!==top)el.style.top=top;if(el.style.getPropertyValue('--bubble-tail')!==tail)el.style.setProperty('--bubble-tail',tail);};
    bubble.observer=new ResizeObserver(position);bubble.observer.observe(host);bubble.observer.observe(el);
    let last=0;const follow=t=>{if(officeBubble!==bubble)return;if(t-last>100){position();last=t;}bubble.frame=requestAnimationFrame(follow);};bubble.frame=requestAnimationFrame(follow);
    el.querySelector('textarea').value=bubbleDrafts.get(id)||'';
    el.querySelector('.bubble-close').onclick=()=>closeOfficeBubble(true);
    el.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();closeOfficeBubble(true);}else if(e.target.tagName==='TEXTAREA'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!el.querySelector('[type=submit]').disabled)el.querySelector('form').requestSubmit();}});
    el.querySelector('form').onsubmit=async e=>{e.preventDefault();if(bubble.sending||bubble.pending||bubble.uploading||!bubble.ready)return;const input=el.querySelector('textarea'),value=input.value.trim();if(!value)return;const attachment=el.querySelector('select').value;const documentIds=[...new Set([...(bubbleAttachments.get(id)||[]).map(d=>d.id),...(attachment?[attachment]:[])])];if(documentIds.length>3){toast('Maksimal 3 lampiran per pesan.');return;}
      bubble.sending=true;el.querySelector('[type=submit]').disabled=true;el.querySelector('.bubble-error').hidden=true;
      try{await api('/api/studio/conversations/'+id,{text:value,documents:documentIds});bubbleDrafts.delete(id);bubbleAttachments.delete(id);paintBubbleAttachments(bubble);if(officeBubble!==bubble)return;input.value='';bubble.revision++;bubble.pending=true;bubble.key='';await loadOfficeBubble();refreshActivity();}
      catch(err){if(officeBubble===bubble){el.querySelector('.bubble-error').textContent=err.message;el.querySelector('.bubble-error').hidden=false;}}
      finally{bubble.sending=false;if(officeBubble===bubble)el.querySelector('[type=submit]').disabled=bubble.pending||!bubble.ready||!state.online||!state.health?.auth?.ready;}
    };
    const uploadFiles=files=>addBubbleFiles(files,bubble).catch(err=>{if(officeBubble===bubble){el.querySelector('.bubble-error').textContent=err.message;el.querySelector('.bubble-error').hidden=false;}});
    el.querySelector('.bubble-upload').onclick=()=>el.querySelector('.bubble-file-input').click();
    el.querySelector('.bubble-file-input').onchange=e=>{uploadFiles(e.target.files);e.target.value='';};
    el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drop-active');});el.addEventListener('dragleave',()=>el.classList.remove('drop-active'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drop-active');uploadFiles(e.dataTransfer.files);});
    el.querySelector('textarea').addEventListener('paste',e=>{const files=Array.from(e.clipboardData?.files||[]);if(files.length){e.preventDefault();uploadFiles(files);}});
    paintBubbleAttachments(bubble);position();loadOfficeBubble();if(matchMedia('(pointer:fine)').matches)el.querySelector('textarea').focus({preventScroll:true});
  }
  async function loadOfficeBubble(){
    const b=officeBubble;if(!b||b.loading)return;b.loading=true;const revision=b.revision;
    try{const c=await api('/api/studio/conversations/'+b.id);if(officeBubble!==b||revision!==b.revision)return;b.ready=true;b.pending=!!c.pending;const key=JSON.stringify(c),messages=b.el.querySelector('.bubble-messages');
      if(key!==b.key){const bottom=!b.key||messages.scrollHeight-messages.scrollTop-messages.clientHeight<80;b.key=key;
        messages.innerHTML=c.messages.length?c.messages.map(m=>`<article class="bubble-message ${m.who==='user'?'user':'agent'}"><small>${m.who==='user'?'Kamu':esc(profile(b.id)[0])}</small><div>${attachmentMarkup(m)}${rich(m.text)}</div></article>`).join(''):`<div class="bubble-empty">Hai, saya ${esc(profile(b.id)[0])}. Mau membahas data atau pekerjaan apa?</div>`;
        if(c.pending)messages.innerHTML+='<div class="bubble-progress"><span class="dot busy"></span> Sedang menyusun jawaban…</div>';
        if(bottom){messages.scrollTop=messages.scrollHeight;messages.querySelectorAll('img').forEach(img=>{if(!img.complete)img.addEventListener('load',()=>{if(officeBubble===b)messages.scrollTop=messages.scrollHeight;},{once:true});});}
      }
      const error=b.el.querySelector('.bubble-error');error.hidden=!c.error;error.textContent=c.error||'';
      b.el.querySelector('[type=submit]').disabled=b.pending||b.sending||!state.online||!state.health?.auth?.ready;
    }catch(err){if(officeBubble===b){b.ready=false;b.el.querySelector('.bubble-error').textContent=err.message;b.el.querySelector('.bubble-error').hidden=false;b.el.querySelector('[type=submit]').disabled=true;}}
    finally{b.loading=false;}
  }
  document.addEventListener('input',e=>{if(e.target.id==='chat-input')drafts.set(state.target,e.target.value);});
  document.addEventListener('click',e=>{
    if(e.target.closest('#office-reset,#scene-back'))selectOfficeDepartment(null);
    const div=e.target.closest('[data-division]');if(div)selectOfficeDepartment(div.dataset.division);
    const brief=e.target.closest('[data-brief-agent]');if(brief){newTask();$('#task-agent').value=brief.dataset.briefAgent;}
    if(e.target.closest('#zoom-in'))state.zoom=Math.min(1.8,Math.round((state.zoom+.2)*10)/10);
    if(e.target.closest('#zoom-out'))state.zoom=Math.max(1,Math.round((state.zoom-.2)*10)/10);
    if(e.target.closest('#zoom-in,#zoom-out')){scene3d?.zoom(e.target.closest('#zoom-in')?.85:1.18);$('#zoom-label').textContent=Math.round(state.zoom*100)+'%';}
    if(e.target.closest('#toggle-motion')){state.motion=!state.motion;scene3d?.setMotion(state.motion);$('#toggle-motion').textContent=state.motion?'Jeda animasi':'Putar animasi';$('#toggle-motion').setAttribute('aria-pressed',String(!state.motion));}
  });
  const api = async (url,data,method) => {
    const opts = {
      method: method || (data !== undefined ? 'POST' : 'GET'),
      headers: { 'Content-Type': 'application/json' }
    };
    if (data !== undefined && opts.method !== 'GET') {
      opts.body = JSON.stringify(data);
    }
    const res = await fetch(url, opts);
    if (!res.ok) {
      const err = await res.json().catch(() => ({ message: res.statusText }));
      throw new Error(err.message || 'Permintaan gagal');
    }
    return await res.json();
  };
  const toast = text => { $('#toast').textContent=text; $('#toast').hidden=false; clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000); };
  const fmt = n => new Intl.NumberFormat('id-ID').format(n);
  const time = n => n ? new Date(n).toLocaleString('id-ID',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
  const status = t => { const k=t.error?'failed':t.state;return `<span class="status ${esc(k)}"><span class="dot ${k==='doing'?'busy':k==='failed'?'error':k==='done'?'online':''}"></span>${({done:'Selesai',doing:'Dikerjakan',next:'Antrean',waiting:'Perlu tinjauan',scheduled:'Terjadwal',failed:'Gagal'})[k]||esc(k)}</span>`; };
  const demoContext = 'Kamu bekerja di NOR ANISA ECOSYSTEM, SaaS B2B Refill Gas & JokiCoding. Gunakan snapshot terbaru untuk MRR, pelanggan, pipeline, support, settlement, dan roadmap. Bedakan fakta, dugaan, dan data yang belum tersedia; jangan mengklaim tindakan eksternal. Jawab Bahasa Indonesia santai.';
  const demoBrief = 'Gunakan tepat 3 teammates: scout untuk analisis, legal untuk validasi fakta, report untuk ringkasan. Lead olead menggabungkan menjadi brief pimpinan maksimal 250 kata: Fakta, Belum diketahui, Tindak lanjut. ' + demoContext;
  const download = (name,content,type='text/plain;charset=utf-8') => {const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
  function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
  $('#close-dialog').onclick=()=>$('#detail-dialog').close();
  $('#detail-dialog').addEventListener('close',()=>{if(!$('#detail-dialog').open)state.taskDialog=null;});
  $('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
  $('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};
  document.addEventListener('click',e=>{if(!e.target.closest('#sidebar,#menu-toggle')){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
  $('#about').onclick=()=>showDialog('Tentang preview', '<p class="about-copy">Nor Anisa AI Business Office Kit. Ini preview statis: seluruh angka, hasil, dan history adalah contoh. Tidak ada koneksi AI, mikrofon, upload, atau integrasi aktif. Kamu dapat menjelajahi fitur; penggunaan sebenarnya memerlukan instalasi sendiri.</p><p class="about-copy">© 2026 djeonail. <a href="./third-party-notices.txt">Lisensi komponen pihak ketiga</a>.</p>');
  const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
  const newButton=()=>`<button class="button primary" data-action="new-task">${icon('plus')} Brief baru</button>`;
  function activeAgent(id){return state.chatting.includes(id)||state.tasks.some(t=>t.state==='doing'&&(t.agent===id||t.team?.pieces?.some(p=>p.agent===id&&p.state==='doing')));}
  function agentStatus(id){if(activeAgent(id))return 'Bekerja';if(state.tasks.some(t=>t.state==='next'&&t.agent===id))return 'Antrean';const latest=[...state.tasks].reverse().find(t=>t.agent===id||t.team?.pieces?.some(p=>p.agent===id));return latest?.state==='done'&&!latest.error?'Selesai · siap':'Siap';}
  function officeVisual(full=false){if(!full)return '<a class="office-launch" href="#office"><span class="eyebrow">VIRTUAL WORKSPACE</span><strong>6 divisi. 35 agent.</strong><span>Masuk kantor 3D →</span><small>Dimuat saat dibuka, supaya overview tetap ringan.</small></a>';return `<div class="scene-container full-scene" id="office-3d" role="region" aria-label="Virtual office 3D"><div class="scene-loading">Menyiapkan kantor 3D…</div><div class="scene-toolbar"><div class="scene-navigation"><button type="button" id="scene-back" aria-label="Kembali ke semua divisi">← Semua divisi</button><select id="scene-department" aria-label="Navigasi departemen"><option value="">Pilih divisi</option>${Object.entries(departments).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></div><button type="button" id="scene-fullscreen" aria-label="Buka fullscreen" aria-pressed="false">⛶ <span>Fullscreen</span></button></div><div class="scene-guide">01 · Pilih blok divisi, lalu klik agent untuk chat</div></div><div class="scene-hint">Drag: putar · Klik kanan / dua jari: geser · Scroll / pinch: zoom</div>`;}
  function taskRows(tasks){return tasks.length?tasks.map(t=>`<button class="task-row" data-task="${esc(t.id)}"><div><div class="task-title">${esc(t.title)}</div><div class="task-meta">${esc(profile(t.agent)[0])}${t.team?' + tim':''} · ${esc(departments[t.dept]||t.dept)}</div></div><span class="task-date muted" style="font-size:10px">${time(t.addedAt)}</span>${status(t)}${icon('chevron')}</button>`).join(''):`<div class="empty"><h3>Ruang untuk ide berikutnya.</h3><p>Kirim brief pertama dan lihat tim menyelesaikannya di sini.</p></div>`;}
  function overview(){return `${heading('NOR ANISA ECOSYSTEM','Ringkasan Operasional · Refill Gas & JokiCoding',newButton())}<section class="hero"><span class="eyebrow">REFILL GAS PORTABLE & JOKICODING</span><h2>Bisnis Terpadu.<br>Satu Tim AI Cerdas.</h2><p>Logistik gas portable, pesanan joki koding, dan layanan akademik bersama 35 agen AI.</p><button class="button primary" data-action="demo">${icon('send')} Buat business brief</button><span class="hero-mark">NOR ANISA / 01</span></section><div class="section-caption"><h2>Performance snapshot</h2><p>September MTD · sampai 18 Sep 2026</p></div><section class="metrics" aria-label="Ringkasan dataset contoh"><div class="metric"><div class="metric-label">Monthly recurring revenue ${icon('chart')}</div><div class="metric-value">Rp 320 jt</div><div class="metric-note"><span class="positive">↗ 6,67%</span> dari Rp300 jt akhir Agustus</div></div><div class="metric"><div class="metric-label">Pelanggan aktif ${icon('office')}</div><div class="metric-value">448</div><div class="metric-note">42 baru · 14 churn September MTD</div></div><div class="metric"><div class="metric-label">ARR run-rate ${icon('chart')}</div><div class="metric-value">Rp 3,84 M</div><div class="metric-note">MRR × 12 · bukan revenue terealisasi</div></div><div class="metric"><div class="metric-label">Logo churn MTD ${icon('chart')}</div><div class="metric-value">3,33<span style="font-size:17px">%</span></div><div class="metric-note">14 dari 420 pelanggan awal periode</div></div></section><section class="workspace-grid"><div class="card"><div class="card-heading"><div><h2>A little office. A capable team.</h2><p>35 agent · 6 divisi · satu perusahaan.</p></div><a href="#office" class="text-button">Buka kantor ${icon('arrow')}</a></div>${officeVisual()}<div class="office-bottom"><span class="inline"><span class="avatar-stack">${Object.keys(profiles).slice(0,4).map(avatar).join('')}</span>NOR ANISA ECOSYSTEM</span><span>${state.tasks.filter(t=>t.state==='doing').length} tugas berjalan</span></div></div><div class="card"><div class="card-heading"><h2>Revenue mix</h2><span class="pill">Insight</span></div><div class="insight-content"><h3 class="insight-title">Growth menyumbang<br>46,88% dari MRR.</h3><p>MRR naik Rp20 juta: Rp32 juta baru dikurangi Rp12 juta churn. Penyebab churn perlu ditelusuri.</p><div class="regions">${[['S','Starter',50,16],['G','Growth',150,47],['S','Scale',120,38]].map(([c,n,v,w])=>`<div class="region-row"><span class="region-left"><span class="region-letter">${c}</span>${n}</span><span class="mini-bar"><span><i style="width:${w}%"></i></span><b class="positive">Rp${v}jt</b></span></div>`).join('')}</div><button class="button cyan" data-action="analyst">Tanya data analyst ${icon('arrow')}</button></div></div></section><section class="card wide-card"><div class="card-heading"><div><h2>Recent work</h2><p>Contoh hasil untuk eksplorasi, bukan eksekusi live.</p></div><a href="#tasks" class="text-button">Semua tugas ${icon('arrow')}</a></div><div id="recent-tasks">${taskRows([...state.tasks].reverse().slice(0,4))}</div></section>`;}
  function office(){const dept=state.officeDept;const team=state.agents.filter(a=>!dept||a.department===dept);const departmentCopy={ops:'Analisis, validasi, dan executive brief.',marketing:'Strategi campaign, konten, dan insight.',sales:'Proposal, prospect research, dan follow-up draft.',fin:'Rekonsiliasi, invoice review, dan analisis.',delivery:'Perencanaan proyek, QA, dan laporan.',emails:'Draft pesan, triase, dan ringkasan komunikasi.'};return `${heading('Meet your team.',`${state.agents.length} agent · 6 divisi · pilih divisi untuk mulai.`,`<button class="button primary" data-chat="team:${dept||'ops'}">${icon('users')} Chat dengan tim</button>`)}<div class="division-grid" role="group" aria-label="Pilih divisi">${Object.entries(departments).map(([key,name])=>`<button class="division ${dept===key?'selected':''}" data-division="${key}"><span class="division-icon">${icon(({ops:'office',marketing:'chart',sales:'users',fin:'database',delivery:'tasks',emails:'chat'})[key])}</span><span><strong>${name}</strong><small>${state.agents.filter(a=>a.department===key).length} agent · ${state.agents.filter(a=>a.department===key&&activeAgent(a.id)).length} bekerja</small></span></button>`).join('')}</div><section class="card office-full"><div class="card-heading"><div><h2>${dept?departments[dept]+' studio':'Explore your office'}</h2><p>${departmentCopy[dept]||'Mulai dari departemen, lalu temui agent yang kamu butuhkan.'}</p></div><div class="office-controls"><button class="button" id="office-reset">Semua divisi</button><button class="icon-button" id="zoom-out" aria-label="Perkecil kantor">−</button><span id="zoom-label">${Math.round(state.zoom*100)}%</span><button class="icon-button" id="zoom-in" aria-label="Perbesar kantor">+</button><button class="button" id="toggle-motion" aria-pressed="${!state.motion}">${state.motion?'Jeda animasi':'Putar animasi'}</button></div></div>${officeVisual(true)}<div class="office-bottom"><span class="inline"><span class="dot busy"></span> Preview · gerak kantor ilustratif</span><span>Klik orang / meja untuk chat</span></div></section><div class="section-caption" style="margin-top:25px"><h2>Your ${(departments[dept]||'whole office').toLowerCase()} team</h2><p>${team.length} specialized agents</p></div><section class="agent-grid">${team.map(a=>`<article class="card agent-card"><div class="agent-top">${avatar(a.id)}<span class="status ${activeAgent(a.id)?'doing':''}" data-agent-status="${a.id}">${agentStatus(a.id)}</span></div><h3>${esc(profile(a.id)[0])}${a.lead?' <span class="pill">Team lead</span>':''}</h3><p>${esc(profile(a.id)[1])}<br>Menganalisis dan menyusun hasil dari data workspace serta lampiranmu.</p><div class="agent-actions"><button class="button" data-chat="${a.id}">${icon('chat')} Chat agent</button><button class="text-button" data-brief-agent="${a.id}">Beri tugas ${icon('arrow')}</button></div></article>`).join('')}</section>`;}
  function chatOptions(){return `<optgroup label="Tim">${Object.entries(departments).map(([id,n])=>`<option value="team:${id}" ${state.target==='team:'+id?'selected':''}>Tim ${n}</option>`).join('')}</optgroup><optgroup label="Agent">${state.agents.map(a=>`<option value="${esc(a.id)}" ${state.target===a.id?'selected':''}>${esc(profile(a.id)[0])} · ${esc(profile(a.id)[1])}</option>`).join('')}</optgroup>`;}
  function chatLabel(){return state.target.startsWith('team:')?[`Tim ${departments[state.target.split(':')[1]]}`,'Lead membagi brief ke agent, lalu merangkum hasil.']:profile(state.target);}
  function attachments(){return `<select class="attachment-select" id="attachment" aria-label="Lampirkan dokumen"><option value="">${state.documents.length?'Tanpa lampiran':'Belum ada dokumen'}</option>${state.documents.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select>`;}
  function chatPage(){const [name,role]=chatLabel();return `<div class="chat-layout"><aside class="chat-list"><h3>Percakapan</h3><input class="search-field" id="agent-search" placeholder="Cari agent atau tim…" aria-label="Cari agent atau tim"><div id="agent-list">${Object.entries(departments).map(([id,n])=>`<button class="chat-person ${state.target==='team:'+id?'active':''}" data-chat="team:${id}"><span class="avatar">${icon('users')}</span><span><strong>Tim ${n}</strong><small>Multi-agent collaboration</small></span></button>`).join('')}<p class="nav-caption" style="margin:21px 10px 10px">DIRECT MESSAGES</p>${state.agents.map(a=>`<button class="chat-person ${state.target===a.id?'active':''}" data-chat="${esc(a.id)}">${avatar(a.id)}<span><strong>${esc(profile(a.id)[0])}</strong><small>${esc(profile(a.id)[1])}</small></span></button>`).join('')}</div></aside><div class="mobile-target"><select id="mobile-agent" aria-label="Pilih agent atau tim">${chatOptions()}</select></div><section class="chat-body"><div class="chat-header">${state.target.startsWith('team:')?`<span class="avatar">${icon('users')}</span>`:avatar(state.target)}<div><h2>${esc(name)}</h2><p>${esc(role)}</p></div><span class="pill">GPT</span></div><div class="messages" id="messages" role="log" aria-label="Riwayat percakapan"><p class="loading">Memuat percakapan…</p></div><form class="composer" id="chat-form"><textarea id="chat-input" maxlength="6000" required placeholder="${state.target.startsWith('team:')?'Tulis brief untuk dikerjakan bersama…':'Apa yang ingin kamu diskusikan?'}" aria-label="Pesan untuk agent"></textarea><div class="composer-footer">${attachments()}<small>Enter kirim · Shift + Enter baris baru</small><button class="button primary" id="send-message" type="submit">${icon('send')} Kirim</button></div></form></section></div>`;}
  function tasksPage(){return `${heading('A clear view of the work.','Setiap brief, progres agent, dan hasil akhir tersimpan di sini.',newButton())}<div class="task-toolbar"><div class="tabs" role="group" aria-label="Filter tugas">${[['all','Semua'],['doing','Berjalan'],['done','Selesai'],['failed','Gagal']].map(([k,n])=>`<button data-filter="${k}" class="${state.filter===k?'active':''}">${n}</button>`).join('')}</div><input class="search-field" id="task-search" placeholder="Cari judul tugas…" aria-label="Cari tugas" value="${esc(state.query)}"></div><section class="card" id="task-list">${filteredTasks()}</section>`;}
  function filteredTasks(){return taskRows([...state.tasks].reverse().filter(t=>(state.filter==='all'||(state.filter==='failed'?t.error:state.filter==='doing'?['doing','next'].includes(t.state):t.state===state.filter&&!t.error))&&t.title.toLowerCase().includes(state.query.toLowerCase())));}
  function dataPage(){return `${heading('Give your team context.','Hubungkan data yang relevan, lalu bicarakan bersama agent.')}<div class="data-grid"><section class="card"><div class="card-heading"><div><h2>Workspace documents</h2><p>Dokumen contoh. Upload dinonaktifkan dalam preview.</p></div><span class="pill">${state.documents.length} files</span></div><div class="card-content"><div class="upload-zone">${icon('upload')}<h3>Bawa datamu ke percakapan.</h3><p>CSV, TXT, Markdown, atau JSON · maksimal 32 KB per file.</p><label class="button primary" for="file-upload">Pilih dokumen</label><input type="file" id="file-upload" accept=".csv,.txt,.md,.json" style="display:block;width:100%;margin-top:12px;font-size:11px"><p>Tidak ada file yang dibaca atau diunggah di halaman preview.</p></div><div id="document-list">${state.documents.map(d=>`<div class="doc-row">${icon('file')}<div><strong>${esc(d.name)}</strong><small>${fmt(d.bytes)} bytes · ${time(d.addedAt)}</small></div><button class="icon-button" data-document="${esc(d.id)}" aria-label="Lihat ${esc(d.name)}">${icon('chevron')}</button><button class="icon-button" data-delete-document="${esc(d.id)}" aria-label="Hapus ${esc(d.name)}">${icon('trash')}</button></div>`).join('')||'<p class="source-note">Belum ada dokumen. Unggah file untuk analisis dengan data pilihanmu.</p>'}</div></div></section><section class="card"><div class="card-heading"><h2>Connections</h2><span class="pill">Private</span></div><div class="card-content">${[['GPT / Codex','Chat agent & kolaborasi tim di VPS.',state.online&&state.health?.auth?.ready?'Preview saja':'Tidak tersedia',state.online&&state.health?.auth?.ready],['Workspace storage','Dokumen, riwayat chat & hasil tersimpan.',state.online?'Preview saja':'Tidak tersedia',state.online],['Google Drive / Sheets','Memerlukan OAuth dan pilihan file.','Belum terhubung',false],['Telegram','Memerlukan bot dan tujuan pengiriman.','Belum terhubung',false],['Email & payment','Tidak ada pengiriman atau transaksi otomatis.','Tidak aktif',false]].map(([n,d,s,yes])=>`<div class="connector"><span class="avatar">${icon('link')}</span><div><h3>${n}</h3><p>${d}</p></div><span class="status ${yes?'done':''}">${s}</span></div>`).join('')}</div></section></div><section class="card wide-card"><div class="card-heading"><div><h2>Subscription plans</h2><p>Harga per workspace per bulan · snapshot 18 September 2026.</p></div><a class="button" href="./sample-subscriptions.csv" download>${icon('download')} CSV</a></div><div class="card-content"><div class="dataset"><table><thead><tr><th>Plan</th><th>Harga bulanan (Rp)</th><th>Pelanggan</th><th>MRR (Rp)</th></tr></thead><tbody>${[['Starter',250000,200],['Growth',750000,200],['Scale',2500000,48]].map(([n,b,a])=>`<tr><td>${n}</td><td>${fmt(b)}</td><td>${fmt(a)}</td><td class="positive">${fmt(a*b)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td>—</td><td><b>448</b></td><td><b>320.000.000</b></td></tr></tbody></table></div><p class="source-note">MRR adalah pendapatan berulang yang dinormalisasi, bukan kas masuk. Katalog ini adalah produk perusahaan demo, bukan penawaran pembelian. Tidak ada akses ke API bisnis produksi.</p></div></section>`;}
  function render(){document.body.classList.remove('office-expanded');closeOfficeBubble();scene3d?.dispose();scene3d=null;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.page);if(a.dataset.nav===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-name').textContent=({overview:'Overview',office:'Virtual office',chat:'Percakapan',tasks:'Tugas & hasil',data:'Data & integrasi'})[state.page];$('#main').innerHTML=({overview,office,chat:chatPage,tasks:tasksPage,data:dataPage})[state.page]();bindPage();if($('#office-3d'))mountOfficeScene($('#office-3d'));if(state.page==='chat'){if($('#chat-input'))$('#chat-input').value=drafts.get(state.target)||'';lastConversation='';loadConversation();}}
  function navigate(){const previousPage=state.page;const [page,target]=location.hash.slice(1).split('/');state.page=['overview','office','chat','tasks','data'].includes(page)?page:'overview';if(state.page==='chat'&&target&&(state.agents.some(a=>a.id===target)||(target.startsWith('team:')&&departments[target.split(':')[1]])))state.target=target;if(state.page==='chat'&&!target)history.replaceState(null,'',`#chat/${state.target}`);if(state.page==='office')state.officeDept=departments[target]?target:null;if(previousPage==='office'&&state.page==='office'&&scene3d&&$('#office-3d')){const template=document.createElement('div');template.innerHTML=office();for(const selector of ['.division-grid','.agent-grid','.page-heading','.office-full .card-heading h2','.office-full .card-heading p','.section-caption']){const old=$('#main '+selector),fresh=template.querySelector(selector);if(old&&fresh)old.replaceWith(fresh);}closeOfficeBubble();scene3d.focus(state.officeDept);syncSceneNavigation();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');return;}$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}
  const goChat=id=>{if(location.hash===`#chat/${id}`){state.target=id;render();}else location.hash=`chat/${id}`;};
  document.addEventListener('click',async e=>{const chat=e.target.closest('[data-chat]');if(chat){goChat(chat.dataset.chat);return;}const task=e.target.closest('[data-task]');if(task){openTask(task.dataset.task);return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='new-task')newTask();if(action==='demo')newTask(true);if(action==='analyst'){goChat('scout');setTimeout(()=>{if($('#chat-input'))$('#chat-input').value='Bantu jelaskan perubahan MRR dan prioritas pengecekan churn. '+demoContext;},20);}
    const doc=e.target.closest('[data-document]');if(doc)try{const d=await api('/api/studio/documents/'+doc.dataset.document);showDialog(d.name,d.type==='image'?`<img class="document-preview" src="${imageURL(d.id)}" alt="${esc(d.name)}">`:`<div class="task-detail">${esc(d.content)}</div>`);}catch(err){toast(err.message);}
    const del=e.target.closest('[data-delete-document]');if(del){const id=del.dataset.deleteDocument;const d=state.documents.find(x=>x.id===id);if(!confirm(`Hapus ${d?.name}? Dokumen sumber di perangkatmu tidak akan dihapus.`))return;try{await api('/api/studio/documents/'+id,undefined,'DELETE');state.documents=await api('/api/studio/documents');render();toast('Dokumen di workspace dihapus. File asli di perangkat tetap ada.');}catch(err){toast(err.message);}}
  });
  function bindPage(){if($('#task-search'))$('#task-search').oninput=e=>{state.query=e.target.value;$('#task-list').innerHTML=filteredTasks();};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render();});if($('#agent-search'))$('#agent-search').oninput=e=>document.querySelectorAll('.chat-person').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if($('#mobile-agent'))$('#mobile-agent').onchange=e=>goChat(e.target.value);if($('#chat-form')){$('#chat-form').onsubmit=sendMessage;$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit();}};}if($('#file-upload'))$('#file-upload').onchange=upload;if(state.page==='data')telegramCard();}
  async function telegramCard(){datasetLibrary();try{state.telegram=await api('/api/studio/telegram');if(state.page!=='data')return;const t=state.telegram;const rows=[...document.querySelectorAll('.connector')];const row=rows.find(r=>r.querySelector('h3')?.textContent.startsWith('Telegram'));if(!row)return;row.innerHTML=`<span class="avatar">${icon('send')}</span><div><h3>Telegram ${t.username?'· @'+esc(t.username):''}</h3><p>${t.paired?'Akun privat sudah dipasangkan.':t.configured?'Bot tersimpan. Pasangkan akun Telegram-mu.':'Chat agent & tim dari bot pribadimu.'}</p><button class="text-button" id="telegram-settings">${t.configured?'Pengaturan bot':'Hubungkan bot'} ${icon('arrow')}</button></div><span class="status ${t.paired&&t.connected?'done':''}">${t.paired&&t.connected?'Terhubung':t.configured?'Menunggu pairing':'Belum terhubung'}</span>`;$('#telegram-settings').onclick=telegramSettings;}catch(err){toast(err.message);}}
  async function datasetLibrary(){if(state.page!=='data'||$('#dataset-library'))return;try{const d=await api('/api/studio/dataset');if(state.page!=='data'||$('#dataset-library'))return;const section=document.createElement('section');section.id='dataset-library';section.className='card wide-card';section.innerHTML=`<div class="card-heading"><div><h2>Knowledge library</h2><p>Snapshot ${esc(d.asOf)} · langsung tersedia bagi semua agent.</p></div><button class="button" id="download-dataset">${icon('download')} JSON</button></div><div class="card-content"><div class="tabs" id="dataset-tabs">${[['daily','Tren harian'],['segments','Funnel'],['campaigns','Campaign'],['settlements','Settlement'],['tickets','Support'],['pipeline','Pipeline'],['roadmap','Roadmap'],['invoices','Invoice'],['payables','Payables']].map(([k,n])=>`<button data-table="${k}">${n}</button>`).join('')}</div><div class="dataset" id="dataset-table" tabindex="0" aria-label="Tabel dataset, geser untuk kolom lainnya"></div><p class="source-note">Coba tanyakan: “Berapa total biaya campaign dan CPA?”, “Channel mana yang settlement-nya selisih?”, atau “Tiket mana yang masih terbuka?”</p><button class="text-button" id="ask-dataset">Diskusikan dengan Nara ${icon('arrow')}</button></div>`;$('#main').append(section);const table=key=>{const rows=d[key];const columns=Object.keys(rows[0]);$('#dataset-table').innerHTML=`<table><thead><tr>${columns.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(k=>`<td>${esc(typeof row[k]==='number'?fmt(row[k]):row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;section.querySelectorAll('[data-table]').forEach(b=>b.classList.toggle('active',b.dataset.table===key));};section.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>table(b.dataset.table));table('daily');$('#download-dataset').onclick=()=>download('djeonail-corp-snapshot.json',JSON.stringify(d,null,2),'application/json');$('#ask-dataset').onclick=()=>goChat('scout');}catch(err){toast(err.message);}}
  async function telegramSettings(){toast('Integrasi Telegram privat dapat dikonfigurasikan di backend.');}
  async function upload(e){
    const file=e.target.files[0];
    if(!file)return;
    const reader=new FileReader();
    reader.onload=async()=>{
      try{
        await api('/api/studio/documents',{name:file.name,content:reader.result,bytes:file.size,type:file.type.startsWith('image/')?'image':'text'},'POST');
        state.documents=await api('/api/studio/documents');
        render();
        toast('Dokumen berhasil diunggah ke workspace.');
      }catch(err){toast(err.message);}
    };
    if(file.type.startsWith('image/'))reader.readAsDataURL(file);
    else reader.readAsText(file);
    e.target.value='';
  }
  function message(who,text,at,name){return `<article class="message ${who==='user'?'user':''}"><div class="message-author">${who==='user'?'Kamu':esc(name)} <span>· ${time(at)}</span></div><div class="message-content">${who==='user'?esc(text):rich(text)}</div></article>`;}
  async function loadConversation(){if(state.page!=='chat')return;const target=state.target;try{let c;if(target.startsWith('team:')){const tasks=state.tasks.filter(t=>t.team&&t.dept===target.split(':')[1]&&t.by==='studio');c={messages:tasks.flatMap(t=>[{who:'user',text:t.title,at:t.addedAt},...(t.result?[{who:'agent',text:t.result,at:t.doneAt}]:[])]),pending:tasks.some(t=>['doing','next'].includes(t.state)),tasks};}else c=await api('/api/studio/conversations/'+target);if(state.page!=='chat'||state.target!==target)return;state.conversation=c;const key=JSON.stringify(c);const messages=$('#messages');if(key!==lastConversation){const nearBottom=messages.scrollHeight-messages.scrollTop-messages.clientHeight<100||!lastConversation;lastConversation=key;messages.innerHTML=c.messages.length?c.messages.map(m=>message(m.who,m.text,m.at,chatLabel()[0])).join(''):`<div class="empty"><h3>Ruang berpikir bersama ${esc(chatLabel()[0])}.</h3><p>Mulai dengan pertanyaan, data, atau pekerjaan yang ingin kamu selesaikan.</p><div class="suggestions"><button data-suggestion="Bantu saya memahami kemampuan dan batasanmu.">Apa yang bisa kamu bantu?</button><button data-suggestion="Ringkas perubahan MRR dan churn NOR ANISA ECOSYSTEM pada snapshot terbaru.">Bahas revenue & retention</button></div></div>`;if(c.pending)messages.innerHTML+=`<div class="message-progress"><span class="dot busy"></span> ${target.startsWith('team:')?'Tim sedang bekerja. Progres tersedia di Tugas & hasil.':'Agent sedang menyusun jawaban… Kamu boleh berpindah halaman.'}</div>`;if(c.error)messages.innerHTML+=`<article class="message error"><div class="message-content">${esc(c.error)}</div></article>`;if(c.tasks?.some(t=>t.state==='doing'))messages.innerHTML+=c.tasks.filter(t=>t.state==='doing').map(t=>`<button class="text-button" data-task="${esc(t.id)}">Lihat progres tim ${icon('arrow')}</button>`).join('');messages.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>{$('#chat-input').value=b.dataset.suggestion;$('#chat-input').focus();});if(nearBottom)messages.scrollTop=messages.scrollHeight;}$('#send-message').disabled=!!c.pending||state.busy||!state.online||!state.health?.auth?.ready;}catch(err){if(state.page==='chat'&&state.target===target){$('#messages').innerHTML=`<div class="empty">${esc(err.message)}</div>`;$('#send-message').disabled=true;}}}
  async function sendMessage(e){e.preventDefault();const input=$('#chat-input'),text=input.value.trim(),target=state.target,documents=$('#attachment').value?[$('#attachment').value]:[];if(!text||state.busy||state.conversation?.pending)return;state.busy=true;$('#send-message').disabled=true;try{if(target.startsWith('team:')){const dept=target.split(':')[1];const lead=state.agents.find(a=>a.department===dept&&a.lead);const prior=state.tasks.filter(t=>t.dept===dept&&t.team&&t.by==='studio'&&t.result&&!t.error).slice(-1)[0];await api('/api/studio/tasks',{text:text+(prior?'\n\nKonteks percakapan sebelumnya (gunakan hanya bila relevan):\n'+prior.result.slice(0,3000):''),agent:lead.id,team:true,documents});state.tasks=await api('/api/tasks');}else await api('/api/studio/conversations/'+target,{text,documents});if(state.page==='chat'&&state.target===target){input.value='';drafts.delete(target);lastConversation='';await loadConversation();}}catch(err){toast(err.message);}finally{state.busy=false;if(state.page==='chat')await loadConversation();}}
  function newTask(demo=false){showDialog(demo?'Daily performance brief':'Brief baru',`<form id="task-form"><label class="form-field">Siapa yang mengerjakan?<select id="task-agent">${state.agents.map(a=>`<option value="${a.id}" ${a.id==='olead'?'selected':''}>${esc(profile(a.id)[0])} · ${esc(departments[a.department])}</option>`).join('')}</select></label><label class="form-field">Brief pekerjaan<textarea id="task-brief" maxlength="6000" required>${demo?esc(demoBrief):''}</textarea></label><label class="inline muted" style="font-size:11px"><input id="task-team" type="checkbox" ${demo?'checked':''}> Kerjakan bersama tim dari departemen ini</label><label class="form-field">Sumber tambahan<select id="task-document"><option value="">Tanpa lampiran</option>${state.documents.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><p class="source-note">Agent menganalisis dan menulis hasil. Pengiriman pesan, transaksi, dan akses akun eksternal belum diaktifkan.</p><div class="dialog-actions"><button class="button primary" id="submit-task">${icon('send')} Kirim brief</button></div></form>`);$('#task-form').onsubmit=async e=>{e.preventDefault();const btn=$('#submit-task');btn.disabled=true;btn.textContent='Mengirim…';try{const t=await api('/api/studio/tasks',{agent:$('#task-agent').value,text:$('#task-brief').value,team:$('#task-team').checked,documents:$('#task-document').value?[$('#task-document').value]:[]});state.tasks=await api('/api/tasks');$('#detail-dialog').close();location.hash='tasks';openTask(t.id);toast('Brief diterima. Agent bekerja di VPS.');}catch(err){toast(err.message);btn.disabled=false;btn.textContent='Kirim brief';}};}
  function taskDetail(t){return `<p class="source-note">${esc(profile(t.agent)[0])}${t.team?' + tim':''} · ${time(t.addedAt)} · ${esc(t.id)}</p><div style="margin-top:12px">${status(t)}</div>${t.team?.pieces?.length?`<div class="progress-list">${t.team.pieces.map(p=>`<div class="progress-piece"><span>${esc(profile(p.agent)[0])} · ${esc(p.title)}</span>${status(p)}</div>`).join('')}</div>`:''}<div class="task-detail" tabindex="0">${rich(t.result||(['doing','next'].includes(t.state)?'Brief diterima. Agent sedang memproses pekerjaan di VPS. Hasil akan muncul otomatis; halaman boleh ditutup.':t.text))}</div>${t.result?`<div class="dialog-actions"><button class="button" id="copy-result">${icon('file')} Salin</button><button class="button primary" id="download-result">${icon('download')} Unduh .md</button></div>`:''}${t.error?'<p class="source-note">Eksekusi gagal. Hasil tidak diganti dengan simulasi. Periksa koneksi atau perpendek brief sebelum mencoba lagi.</p>':''}`;}
  function openTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;showDialog(t.title,taskDetail(t));state.taskDialog=id;bindResult(t);}
  function bindResult(t){if($('#download-result')){$('#download-result').onclick=()=>download(`agent-office-${t.id}.md`,`# ${t.title}\n\n${t.result}`);if(!t.error){const b=document.createElement('button');b.className='button';b.innerHTML=icon('send')+' Kirim ke Telegram';b.onclick=async()=>{if(!confirm('Kirim hasil ini ke akun Telegram yang dipasangkan?'))return;b.disabled=true;try{await api('/api/studio/telegram/send',{taskId:t.id});toast('Hasil terkirim ke Telegram.');}catch(err){toast(err.message);}finally{b.disabled=false;}};$('#download-result').before(b);}}if($('#copy-result'))$('#copy-result').onclick=async()=>{try{await navigator.clipboard.writeText(t.result);toast('Hasil disalin.');}catch{toast('Clipboard tidak tersedia. Pilih teks hasil untuk menyalin.');}};}
  async function refresh(silent=false){if(state.refreshing)return;state.refreshing=true;try{const [health,tasks,docs]=await Promise.all([api('/api/health'),api('/api/tasks'),api('/api/studio/documents')]);state.health=health;state.agents=health.agents;state.tasks=tasks;state.documents=docs;state.online=true;$('#connection').innerHTML=`<span class="dot ${health.auth?.ready?'online':'error'}"></span> ${health.ok?'AI Online · 35 Agen':'Offline'}`;$('#task-count').textContent=tasks.filter(t=>['next','doing'].includes(t.state)).length;const changed=lastTasks!==JSON.stringify(tasks);lastTasks=JSON.stringify(tasks);if(!silent)navigate();else if(changed){if($('#recent-tasks'))$('#recent-tasks').innerHTML=taskRows([...tasks].reverse().slice(0,4));if($('#task-list'))$('#task-list').innerHTML=filteredTasks();if(state.taskDialog&&$('#detail-dialog').open){const t=tasks.find(t=>t.id===state.taskDialog);if(t){const scroll=$('#dialog-content .task-detail')?.scrollTop||0;$('#dialog-content').innerHTML=taskDetail(t);bindResult(t);$('#dialog-content .task-detail').scrollTop=scroll;}}document.querySelectorAll('.office-node').forEach(n=>n.querySelector('.dot').className='dot '+(activeAgent(n.dataset.chat)?'busy':''));}if(state.page==='chat')await loadConversation();}catch(err){state.online=false;$('#connection').innerHTML='<span class="dot error"></span> Koneksi terputus';if(!silent){$('#main').innerHTML=`<div class="empty"><h3>Workspace belum dapat dimuat.</h3><p>${esc(err.message)}</p><button class="button" id="retry-load" style="margin-top:16px">Coba lagi</button></div>`;$('#retry-load').onclick=()=>refresh();}if($('#send-message'))$('#send-message').disabled=true;}finally{state.refreshing=false;}}
  $('#refresh').onclick=async()=>{await refresh(true);toast(state.online?'Data workspace diperbarui.':'Koneksi terputus. Coba lagi.');};
  window.addEventListener('hashchange',()=>{if(state.agents.length)navigate();});
  $('#main').innerHTML='<p class="loading">Menyiapkan workspace…</p>';
  async function refreshActivity(){try{state.chatting=(await api('/api/studio/activity')).chatting;scene3d?.update(state.chatting,state.tasks);document.querySelectorAll('[data-agent-status]').forEach(el=>{el.textContent=agentStatus(el.dataset.agentStatus);el.className='status '+(activeAgent(el.dataset.agentStatus)?'doing':'');});document.querySelectorAll('.office-node').forEach(el=>{el.querySelector('.dot').className='dot '+(activeAgent(el.dataset.chat)?'busy':'');if(state.page==='office')el.querySelector('small').textContent=agentStatus(el.dataset.chat);});document.querySelectorAll('[data-worker]').forEach(el=>el.classList.toggle('working',activeAgent(el.dataset.worker)));}catch{}}
  refresh();setInterval(()=>{if(!document.hidden){refresh(true);refreshActivity();loadOfficeBubble();if(state.page==='data')telegramCard();}},4500);
})();
